#!/usr/bin/env node
import {
  exportRecipe
} from "./chunk-PS42E7L3.js";
import {
  NUTRITION_BASIS_FLAG_DESCRIPTION,
  parseNutritionBasis
} from "./chunk-CZEB27I3.js";
import {
  resolveScaleArg
} from "./chunk-E4B6DFAN.js";
import {
  resolveStockFromConfig
} from "./chunk-EXIXW6Q5.js";
import "./chunk-JCFG34DV.js";
import "./chunk-XW73TKNN.js";
import "./chunk-4MSISIPG.js";
import {
  reportRejectedIngredients
} from "./chunk-4A6RJKSG.js";
import {
  loadDbSafe
} from "./chunk-J5CTY35W.js";
import {
  loadConfig
} from "./chunk-LYQHWV53.js";
import "./chunk-IWNALT6P.js";
import "./chunk-5APUWLPI.js";
import {
  ExitCode,
  GramCLIError
} from "./chunk-IXNX2GX7.js";

// src/commands/export.ts
import { defineCommand } from "citty";
import { writeFile } from "fs/promises";
import { resolve, join, dirname, basename, extname } from "path";
import { log } from "@clack/prompts";
import chalk from "chalk";
var export_default = defineCommand({
  meta: {
    name: "export",
    description: "Export a recipe to Markdown or print-ready HTML"
  },
  args: {
    file: {
      type: "positional",
      required: true,
      description: "Path to a .gram recipe file"
    },
    format: {
      type: "string",
      description: "Output format: md (Markdown) or html (print-ready A4 HTML)"
    },
    output: {
      type: "string",
      alias: "o",
      description: "Output file path (default: same directory as input, with new extension)"
    },
    scale: {
      type: "string",
      description: "Scale factor (e.g. 1.5) or reference ingredient (e.g. farine=300g)"
    },
    db: {
      type: "string",
      description: "Path to ingredient database YAML"
    },
    "skip-db": {
      type: "boolean",
      description: "Skip ingredient database",
      default: false
    },
    "step-qty": {
      type: "boolean",
      description: "HTML only: show ingredient quantities in step text (pass --no-step-qty to hide; quantities in section mise en place are always shown)",
      default: true
    },
    "bakers-math": {
      type: "boolean",
      description: "Display ingredient quantities as a percentage of a reference ingredient (Baker's Percentage)."
    },
    "bakers-reference": {
      type: "string",
      description: "Force a specific ingredient as the baker's math reference (e.g. flour). Implies --bakers-math"
    },
    "bakers-math-only": {
      type: "boolean",
      description: "Only show the percentages and hide absolute weights."
    },
    nutrition: {
      type: "string",
      description: NUTRITION_BASIS_FLAG_DESCRIPTION
    },
    stock: {
      type: "string",
      description: "Comma-separated @use specifiers already on hand for this export (e.g. @bases/pate.gram,./levain.gram)"
    }
  },
  async run({ args }) {
    const fmt = args.format;
    if (!fmt || fmt !== "md" && fmt !== "html") {
      log.error("--format is required. Use --format md or --format html.");
      process.exit(ExitCode.Error);
    }
    const filePath = resolve(args.file);
    const config = await loadConfig();
    const dbResult = args["skip-db"] ? null : await loadDbSafe(config, args.db);
    if (dbResult) reportRejectedIngredients(dbResult.rejected, dbResult.dbPath);
    const db = dbResult?.data ?? null;
    const scaleFactor = await resolveScaleArg(
      args.scale,
      filePath,
      db,
      config.language,
      config.paths
    );
    const bakersReference = args["bakers-reference"] || (args["bakers-math"] ? "" : void 0);
    const bakersMathOnly = args["bakers-math-only"];
    const nutritionBasis = parseNutritionBasis(args.nutrition);
    const stock = resolveStockFromConfig(args.stock, config);
    const outputPath = args.output ? resolve(args.output) : join(
      dirname(filePath),
      `${basename(filePath, extname(filePath))}.${fmt}`
    );
    let content;
    try {
      content = await exportRecipe(filePath, fmt, db, scaleFactor, {
        hideStepQty: !args["step-qty"],
        bakersReference,
        bakersMathOnly,
        nutritionBasis,
        lang: config.language,
        paths: config.paths,
        stock
      });
    } catch (err) {
      if (err instanceof GramCLIError) {
        log.error(err.message);
        process.exit(err.exitCode);
      }
      throw err;
    }
    await writeFile(outputPath, content, "utf-8");
    log.success(`Exported to ${chalk.dim(outputPath)}`);
  }
});
export {
  export_default as default
};
